    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink-soft);
    font-family: var(--font-mono);
  }
  .stat .value {
    font-family: var(--font-display);
    font-size: 22px;
    margin-top: 6px;
    font-variant-numeric: tabular-nums;
  }
  .stat .value.ok { color: var(--done); }
  .stat .value.wait { color: var(--decision); }

  /* ---- Section ---- */
  section { margin-bottom: 40px; }
  .section-head {
    display: flex;
    align-items: baseline;
    gap: 10px;
    border-bottom: 1px solid var(--line);
    padding-bottom: 10px;
    margin-bottom: 4px;
  }
  .section-head h2 {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: 19px;
    margin: 0;
  }
  .section-head .count {
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--ink-soft);
    font-variant-numeric: tabular-nums;
  }

  /* ---- Ledger rows ---- */
  .ledger-row {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 16px;
    align-items: start;
    padding: 14px 2px;
    border-bottom: 1px solid var(--line);
  }
  .ledger-row:last-child { border-bottom: none; }
  .ledger-row .name {
    font-weight: 600;
    font-size: 14.5px;
  }
  .ledger-row .note {
    color: var(--ink-soft);
    font-size: 13px;
    margin-top: 3px;
    max-width: 62ch;
  }
  .chip {
    font-family: var(--font-mono);
    font-size: 11px;
    letter-spacing: 0.03em;
    padding: 4px 9px;
    border-radius: 3px;
    white-space: nowrap;
    align-self: center;
  }
  .chip.done { background: var(--done-soft); color: var(--done); }
  .chip.decision { background: var(--decision-soft); color: var(--decision); }
  .chip.gap { background: var(--gap-soft); color: var(--gap); }
  .chip.waiting { background: var(--waiting-soft); color: var(--waiting); }

  /* ---- Condensed strip (core engine) ---- */
  .strip {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 10px;
    padding: 4px 2px 2px;
  }
  .strip-item {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    color: var(--ink-soft);
  }
  .strip-item::before {
    content: "";
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--done);
    flex-shrink: 0;
  }

  /* ---- Callout ---- */
  .callout {
    background: var(--surface);
    border: 1px solid var(--line);
    border-left: 3px solid var(--waiting);
    padding: 16px 18px;
    margin: 8px 0 0;
  }
  .callout .name {
    font-weight: 600;
    font-size: 14.5px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .callout .note {
    color: var(--ink-soft);
    font-size: 13px;
    margin-top: 6px;
    max-width: 66ch;
  }
  .callout .filelist {
    font-family: var(--font-mono);
    font-size: 12px;
    color: var(--ink-soft);
    margin-top: 10px;
    line-height: 1.7;
  }

  /* ---- Priority list ---- */
  .priority {
    list-style: none;
    margin: 0;
    padding: 0;
    counter-reset: pri;
  }
  .priority li {
    counter-increment: pri;
    display: grid;
    grid-template-columns: 32px 1fr;
