"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { logActivity } from "@/lib/activity-log";

function parseEmployeeFields(formData: FormData) {
  const name = (formData.get("name") as string)?.trim();
  const dailyRateRaw = formData.get("dailyRate") as string;
  const note = (formData.get("note") as string)?.trim();
  const cashierId = (formData.get("cashierId") as string) || null;

  if (!name) return { error: "Nama karyawan wajib diisi." } as const;

  const dailyRate = dailyRateRaw ? Number(dailyRateRaw) : 0;
  if (Number.isNaN(dailyRate) || dailyRate < 0) {
    return { error: "Gaji harian harus angka dan tidak boleh negatif." } as const;
  }

  return { error: null, name, dailyRate, note: note || null, cashierId } as const;
}

export type AddEmployeeState = { error: string | null };

export async function addEmployee(
  businessId: string,
  _prevState: AddEmployeeState,
  formData: FormData,
): Promise<AddEmployeeState> {
  const parsed = parseEmployeeFields(formData);
  if (parsed.error !== null) return { error: parsed.error };

  const supabase = await createClient();
  const { error } = await supabase.from("employees").insert({
    business_id: businessId,
    name: parsed.name,
    daily_rate: parsed.dailyRate,
    note: parsed.note,
    cashier_id: parsed.cashierId,
  });

  if (error) {
    if (error.code === "23505") {
      return { error: "Akun kasir itu sudah dihubungkan ke karyawan lain." };
    }
    return { error: error.message };
  }

  await logActivity(supabase, businessId, "pengaturan", "sukses", `Karyawan baru: ${parsed.name}`);
  revalidatePath(`/business/${businessId}/employees`);
  return { error: null };
}

export type EditEmployeeState = { error: string | null };

export async function editEmployee(
  businessId: string,
  employeeId: string,
  _prevState: EditEmployeeState,
  formData: FormData,
): Promise<EditEmployeeState> {
  const parsed = parseEmployeeFields(formData);
  if (parsed.error !== null) return { error: parsed.error };

  const supabase = await createClient();
  const { error } = await supabase
    .from("employees")
    .update({
      name: parsed.name,
      daily_rate: parsed.dailyRate,
      note: parsed.note,
      cashier_id: parsed.cashierId,
    })
    .eq("id", employeeId)
    .eq("business_id", businessId);

  if (error) {
    if (error.code === "23505") {
      return { error: "Akun kasir itu sudah dihubungkan ke karyawan lain." };
    }
    return { error: error.message };
  }

  await logActivity(supabase, businessId, "pengaturan", "info", `Karyawan diubah: ${parsed.name}`);
  revalidatePath(`/business/${businessId}/employees`);
  return { error: null };
}

export async function setEmployeeActive(businessId: string, employeeId: string, active: boolean) {
  const supabase = await createClient();

  const { data: employee } = await supabase
    .from("employees")
    .select("name")
    .eq("id", employeeId)
    .eq("business_id", businessId)
    .maybeSingle();

  await supabase
    .from("employees")
    .update({ active })
    .eq("id", employeeId)
    .eq("business_id", businessId);

  if (employee) {
    await logActivity(
      supabase,
      businessId,
      "pengaturan",
      active ? "sukses" : "warning",
      `Karyawan ${active ? "diaktifkan" : "dinonaktifkan"}: ${employee.name}`,
    );
  }
  revalidatePath(`/business/${businessId}/employees`);
}

"use client";

import { useActionState, useRef, useEffect } from "react";
import type { AddEmployeeState } from "./actions";

const initialState: AddEmployeeState = { error: null };

export default function AddEmployeeForm({
  cashiers,
  action,
}: {
  cashiers: { id: string; name: string }[];
  action: (state: AddEmployeeState, formData: FormData) => Promise<AddEmployeeState>;
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
    }
  }, [pending, state.error]);

  return (
    <form ref={formRef} action={formAction} className="space-y-4">
      <div>
        <label htmlFor="name" className="mb-1 block text-xs font-medium text-zinc-600">
          Nama Karyawan
        </label>
        <input
          id="name"
          name="name"
          type="text"
          required
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          placeholder="mis. Siti"
        />
      </div>

      <div>
        <label htmlFor="dailyRate" className="mb-1 block text-xs font-medium text-zinc-600">
          Gaji Harian (Rp, opsional)
        </label>
        <input
          id="dailyRate"
          name="dailyRate"
          type="number"
          min="0"
          step="1"
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          placeholder="mis. 100000"
        />
      </div>

      <div>
        <label htmlFor="note" className="mb-1 block text-xs font-medium text-zinc-600">
          Jabatan/Catatan (opsional)
        </label>
        <input
          id="note"
          name="note"
          type="text"
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
          placeholder="mis. Juru masak"
        />
      </div>

      <div>
        <label htmlFor="cashierId" className="mb-1 block text-xs font-medium text-zinc-600">
          Akun Kasir Terhubung (opsional)
        </label>
        <select
          id="cashierId"
          name="cashierId"
          defaultValue=""
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        >
          <option value="">Tidak pegang kasir</option>
          {cashiers.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name}
            </option>
          ))}
        </select>
        <p className="mt-1 text-[11px] text-zinc-400">
          Isi kalau karyawan ini juga login ke layar kasir, supaya tidak double catat.
        </p>
      </div>

      {state.error && (
        <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{state.error}</p>
      )}

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {pending ? "Menyimpan…" : "Tambah Karyawan"}
      </button>
    </form>
  );
}

