"use client";

import { useRef, useState } from "react";
import AddPurchaseForm, { type PurchasePrefill } from "./add-purchase-form";
import type { AddPurchaseState } from "./actions";

type SupplierOption = { id: string; name: string };
type IngredientOption = { id: string; name: string; unit: string; stock: number };
type ProductOption = { id: string; name: string; stock: number };

type LowStockIngredient = {
  id: string;
  name: string;
  unit: string;
  stock: number;
  minStock: number;
  suggestedQty: number;
  unitCost: number;
};

type LowStockProduct = {
  id: string;
  name: string;
  stock: number;
  minStock: number;
  suggestedQty: number;
  unitCost: number;
};

function formatRupiah(value: number) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

export default function PurchaseFormWithRecommendations({
  action,
  today,
  isFnb,
  suppliers,
  ingredients,
  products,
  lowStockIngredients,
  lowStockProducts,
}: {
  action: (state: AddPurchaseState, formData: FormData) => Promise<AddPurchaseState>;
  today: string;
  isFnb: boolean;
  suppliers: SupplierOption[];
  ingredients: IngredientOption[];
  products: ProductOption[];
  lowStockIngredients: LowStockIngredient[];
  lowStockProducts: LowStockProduct[];
}) {
  const [prefill, setPrefill] = useState<PurchasePrefill | null>(null);
  const formRef = useRef<HTMLDivElement>(null);

  const hasRecommendations = lowStockIngredients.length > 0 || lowStockProducts.length > 0;

  function selectRecommendation(next: PurchasePrefill) {
    setPrefill(next);
    formRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  return (
    <>
      {hasRecommendations && (
        <div className="mt-4 rounded-xl bg-white shadow-sm p-5">
          <h2 className="text-sm font-semibold text-zinc-900">
            📋 Rekomendasi Pembelian (Stok Rendah)
          </h2>
          <p className="mt-1 text-xs text-zinc-500">
            Saran qty menutup stok kembali ke 2x stok minimum — tetap bisa diubah di form.
          </p>
          <div className="mt-3 space-y-2">
            {lowStockIngredients.map((i) => (
              <div
                key={i.id}
                className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-amber-50 px-3 py-2"
              >
                <div className="min-w-0">
                  <p className="truncate text-xs font-semibold text-amber-900">{i.name}</p>
                  <p className="text-[11px] text-amber-700">
                    Stok {i.stock} {i.unit} (min {i.minStock}) · Saran beli {i.suggestedQty}{" "}
                    {i.unit}
                    {i.unitCost > 0 && ` · ~${formatRupiah(i.suggestedQty * i.unitCost)}`}
                  </p>
                </div>
                <button
                  onClick={() =>
                    selectRecommendation({
                      category: "Bahan Baku",
                      itemId: i.id,
                      qty: i.suggestedQty,
                      amount: Math.round(i.suggestedQty * i.unitCost),
                    })
                  }
                  className="shrink-0 rounded-lg bg-amber-600 px-3 py-1.5 text-xs font-semibold text-white transition-colors hover:bg-amber-700"
                >
                  Beli Sekarang
                </button>
              </div>
            ))}
            {lowStockProducts.map((p) => (
              <div
                key={p.id}
                className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-blue-50 px-3 py-2"
              >
                <div className="min-w-0">
                  <p className="truncate text-xs font-semibold text-blue-900">{p.name}</p>
                  <p className="text-[11px] text-blue-700">
                    Stok {p.stock} (min {p.minStock}) · Saran beli {p.suggestedQty}
                    {p.unitCost > 0 && ` · ~${formatRupiah(p.suggestedQty * p.unitCost)}`}
                  </p>
                </div>
                <button
                  onClick={() =>
                    selectRecommendation({
                      category: "Barang Dagang",
                      itemId: p.id,
                      qty: p.suggestedQty,
                      amount: Math.round(p.suggestedQty * p.unitCost),
                    })
                  }
                  className="shrink-0 rounded-lg bg-blue-600 px-3 py-1.5 text-xs font-semibold text-white transition-colors hover:bg-blue-700"
                >
                  Beli Sekarang
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div ref={formRef} className="mt-4 rounded-xl bg-white shadow-sm p-5">
        <h2 className="mb-4 text-sm font-semibold text-zinc-900">+ Catat Pembelian</h2>
        <AddPurchaseForm
          action={action}
          today={today}
          isFnb={isFnb}
          suppliers={suppliers}
          ingredients={ingredients}
          products={products}
          prefill={prefill}
        />
      </div>
    </>
  );
}

-- Mini-ERP: supplier directory + formal pembelian records with utang dagang
-- (accounts payable) tracking. Additive only — the existing "Catat
-- Pengeluaran" purchase categories in finance/actions.ts are untouched; this
-- is a separate, more structured flow for purchases tied to a supplier that
-- may be paid partially or entirely on credit.

create table public.suppliers (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  name text not null,
  phone text,
  address text,
  notes text,
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);

create index suppliers_business_id_idx on public.suppliers (business_id);

alter table public.suppliers enable row level security;

create policy "Owner manages suppliers of own businesses"
on public.suppliers for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

create table public.purchases (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  supplier_id uuid references public.suppliers (id) on delete set null,
  date date not null default current_date,
  category text not null check (category in ('Bahan Baku', 'Barang Dagang')),
  ingredient_id uuid references public.ingredients (id) on delete set null,
  product_id uuid references public.products (id) on delete set null,
  qty numeric(12, 2),
  note text,
  amount numeric(14, 2) not null check (amount > 0),
  paid_amount numeric(14, 2) not null default 0 check (paid_amount >= 0),
  created_at timestamptz not null default now(),
  constraint purchases_paid_not_over_amount check (paid_amount <= amount)
);

create index purchases_business_id_idx on public.purchases (business_id, date desc);
create index purchases_supplier_id_idx on public.purchases (supplier_id);

alter table public.purchases enable row level security;

create policy "Owner manages purchases of own businesses"
on public.purchases for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

create table public.purchase_payments (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  purchase_id uuid not null references public.purchases (id) on delete cascade,
  date date not null default current_date,
  amount numeric(14, 2) not null check (amount > 0),
  note text,
  created_at timestamptz not null default now()
);

create index purchase_payments_purchase_id_idx on public.purchase_payments (purchase_id, created_at desc);
create index purchase_payments_business_id_idx on public.purchase_payments (business_id);

alter table public.purchase_payments enable row level security;

create policy "Owner manages purchase payments of own businesses"
on public.purchase_payments for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

