-- Module: customer/member management. Customers are optional — a
-- transaction can be linked to one at checkout to build purchase history,
-- but walk-in sales without a customer remain fully supported.

create table public.customers (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  name text not null,
  phone text,
  email text,
  note text,
  deleted_at timestamptz,
  created_at timestamptz not null default now()
);

create index customers_business_id_idx on public.customers (business_id);
-- Phone only needs to be unique among live (non-deleted) customers of a business.
create unique index customers_business_id_phone_key
  on public.customers (business_id, phone)
  where phone is not null and deleted_at is null;

alter table public.customers enable row level security;

create policy "Owner manages customers of own businesses"
on public.customers for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

-- Link transactions to an (optional) customer -----------------------------

alter table public.transactions
  add column if not exists customer_id uuid references public.customers (id) on delete set null;

create index transactions_customer_id_idx on public.transactions (customer_id);

-- checkout_transaction now accepts an optional customer to attach ---------

drop function if exists public.checkout_transaction(uuid, uuid, jsonb, text, numeric, numeric, text);

create or replace function public.checkout_transaction(
  p_business_id uuid,
  p_cashier_id uuid,
  p_items jsonb, -- array of {product_id, qty, disc, disc_type}
  p_payment_method text,
  p_received numeric default null,
  p_order_disc numeric default 0,
  p_order_disc_type text default 'pct',
  p_customer_id uuid default null
)
returns table (transaction_id uuid, invoice_number text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_business record;
  v_invoice_number text;
  v_seq int;
  v_subtotal_raw numeric(12, 2) := 0;
  v_total_item_disc numeric(12, 2) := 0;
  v_order_disc_amt numeric(12, 2) := 0;
  v_subtotal numeric(12, 2);
  v_service numeric(12, 2) := 0;
  v_tax numeric(12, 2) := 0;
  v_total numeric(12, 2);
  v_total_cost numeric(12, 2) := 0;
  v_transaction_id uuid;
  v_item jsonb;
  v_qty numeric(12, 2);
  v_product_id uuid;
  v_product record;
  v_line_gross numeric(12, 2);
  v_disc numeric(12, 2);
  v_disc_type text;
  v_item_disc numeric(12, 2);
  v_change numeric(12, 2);
  v_shift_id uuid;
  v_recipe record;
begin
  if not private.owns_business(p_business_id) then
    raise exception 'not authorized';
  end if;

  if not exists (
    select 1 from public.cashiers c
    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
  ) then
    raise exception 'invalid cashier';
  end if;

  if p_customer_id is not null and not exists (
    select 1 from public.customers c
    where c.id = p_customer_id and c.business_id = p_business_id and c.deleted_at is null
  ) then
    raise exception 'invalid customer';
  end if;

  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
    raise exception 'payment method required';
  end if;

  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'cart is empty';
  end if;

  if p_order_disc_type not in ('pct', 'amt') then
    raise exception 'invalid order discount type';
  end if;

  if p_order_disc is null or p_order_disc < 0
     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
    raise exception 'invalid order discount';
  end if;

  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
  into v_business
  from public.businesses b
  where b.id = p_business_id;

  select id into v_shift_id
  from public.shifts
  where business_id = p_business_id and closed_at is null
  limit 1;

  if v_shift_id is null then
    raise exception 'no active shift — open a shift before selling';
  end if;

  select count(*) + 1 into v_seq
  from public.transactions t
  where t.business_id = p_business_id
    and t.date::date = current_date;

  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');

  insert into public.transactions (
    business_id, shift_id, cashier_id, customer_id, invoice_number, date,
    subtotal_raw, subtotal, total, total_cost, gross_profit
  ) values (
    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_invoice_number, now(),
    0, 0, 0, 0, 0
  )
  returning id into v_transaction_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    v_product_id := (v_item ->> 'product_id')::uuid;
    v_qty := (v_item ->> 'qty')::numeric;
    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');

    if v_qty is null or v_qty <= 0 then
      raise exception 'invalid quantity';
    end if;

    if v_disc_type not in ('pct', 'amt') then
      raise exception 'invalid item discount type';
    end if;

    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
      raise exception 'invalid item discount';
    end if;

    select * into v_product
    from public.products p
    where p.id = v_product_id
      and p.business_id = p_business_id
      and p.deleted_at is null;

    if not found then
      raise exception 'product not found: %', v_product_id;
    end if;

    v_line_gross := v_product.price * v_qty;
    v_item_disc := case v_disc_type
      when 'pct' then round(v_line_gross * v_disc / 100)
      else least(v_disc * v_qty, v_line_gross)
    end;

    insert into public.transaction_items (
      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
    ) values (
      v_transaction_id, v_product.id, v_product.name, v_product.category,
      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
    );

    update public.products
    set stock = greatest(0, stock - v_qty)
    where id = v_product_id;

    -- Consume ingredients per the product's recipe (if any).
    for v_recipe in
      select pr.ingredient_id, pr.qty as recipe_qty
      from public.product_recipes pr
      where pr.product_id = v_product_id and pr.ingredient_id is not null
    loop
      insert into public.transaction_ingredient_consumption (
        transaction_id, ingredient_id, qty
      ) values (
        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
      );

      update public.ingredients
      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
      where id = v_recipe.ingredient_id;
    end loop;

    v_subtotal_raw := v_subtotal_raw + v_line_gross;
    v_total_item_disc := v_total_item_disc + v_item_disc;
    v_total_cost := v_total_cost + v_product.cost * v_qty;
  end loop;

  v_order_disc_amt := case p_order_disc_type
    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
  end;

  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;

  if v_business.service_enabled then
    v_service := round(v_subtotal * v_business.service_rate / 100);
  end if;

  if v_business.tax_enabled then
    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
  end if;

  v_total := v_subtotal + v_service + v_tax;

  update public.transactions
  set subtotal_raw = v_subtotal_raw,
      subtotal = v_subtotal,
      total_item_disc = v_total_item_disc,
      order_disc_amt = v_order_disc_amt,
      service = v_service,
      tax = v_tax,
      total = v_total,
      total_cost = v_total_cost,
      gross_profit = v_subtotal - v_total_cost
  where id = v_transaction_id;

  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);

  insert into public.transaction_payments (
    transaction_id, method, amount, received, change
  ) values (
    v_transaction_id, p_payment_method, v_total, p_received, v_change
  );

  return query select v_transaction_id, v_invoice_number;
end;
$$;

grant execute on function public.checkout_transaction(uuid, uuid, jsonb, text, numeric, numeric, text, uuid) to authenticated;

-- Mini-ERP accounting module, part 1: Chart of Accounts + double-entry
-- journal. Additive only — does not touch existing checkout/expense/payroll
-- behavior in this migration (auto-posting is wired in follow-up migrations).

create table public.accounts (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  code text not null,
  name text not null,
  type text not null check (type in ('aset', 'kewajiban', 'modal', 'pendapatan', 'beban')),
  normal_balance text not null check (normal_balance in ('debit', 'kredit')),
  is_system boolean not null default false,
  created_at timestamptz not null default now()
);

create unique index accounts_business_id_code_key on public.accounts (business_id, code);
create index accounts_business_id_idx on public.accounts (business_id);

alter table public.accounts enable row level security;

create policy "Owner manages accounts of own businesses"
on public.accounts for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

-- Journal entries (header) ---------------------------------------------------

create table public.journal_entries (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  date timestamptz not null default now(),
  description text not null,
  source text not null default 'manual' check (
    source in ('manual', 'penjualan', 'void', 'pembelian', 'beban', 'payroll')
  ),
  source_id uuid,
  created_at timestamptz not null default now()
);

create index journal_entries_business_id_idx on public.journal_entries (business_id);
create index journal_entries_source_idx on public.journal_entries (source, source_id);

alter table public.journal_entries enable row level security;

-- Read-only from the client's perspective — every entry must balance, so
-- writes only ever happen through private.post_journal() (called from
-- security-definer RPCs). Direct client inserts/updates/deletes would risk
-- unbalanced entries, so no write policy is granted here.
create policy "Owner views journal entries of own businesses"
on public.journal_entries for select
using (private.owns_business(business_id));

-- Journal lines (debit/credit rows) ------------------------------------------

create table public.journal_lines (
  id uuid primary key default gen_random_uuid(),
  entry_id uuid not null references public.journal_entries (id) on delete cascade,
  account_id uuid not null references public.accounts (id),
  debit numeric(14, 2) not null default 0,
  credit numeric(14, 2) not null default 0,
  constraint journal_lines_one_sided check (
    (debit > 0 and credit = 0) or (credit > 0 and debit = 0)
  )
);

create index journal_lines_entry_id_idx on public.journal_lines (entry_id);
create index journal_lines_account_id_idx on public.journal_lines (account_id);

alter table public.journal_lines enable row level security;

create policy "Owner views journal lines of own businesses"
on public.journal_lines for select
using (
  exists (
    select 1 from public.journal_entries je
    where je.id = journal_lines.entry_id
      and private.owns_business(je.business_id)
  )
);

-- Default Indonesian F&B/retail chart of accounts ----------------------------

create or replace function private.seed_default_accounts(p_business_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.accounts (business_id, code, name, type, normal_balance, is_system)
  values
    (p_business_id, '1-001', 'Kas & Bank', 'aset', 'debit', true),
    (p_business_id, '1-100', 'Piutang Usaha', 'aset', 'debit', true),
    (p_business_id, '1-200', 'Persediaan', 'aset', 'debit', true),
    (p_business_id, '1-500', 'Peralatan', 'aset', 'debit', true),
    (p_business_id, '2-001', 'Utang Dagang', 'kewajiban', 'kredit', true),
    (p_business_id, '2-100', 'Utang Gaji', 'kewajiban', 'kredit', true),
    (p_business_id, '3-001', 'Modal Pemilik', 'modal', 'kredit', true),
    (p_business_id, '3-100', 'Laba Ditahan', 'modal', 'kredit', true),
    (p_business_id, '4-001', 'Pendapatan Penjualan', 'pendapatan', 'kredit', true),
    (p_business_id, '5-001', 'Beban Pokok Penjualan (HPP)', 'beban', 'debit', true),
    (p_business_id, '5-100', 'Beban Gaji', 'beban', 'debit', true),
    (p_business_id, '5-101', 'Beban Listrik & Air', 'beban', 'debit', true),
    (p_business_id, '5-102', 'Beban Sewa', 'beban', 'debit', true),
    (p_business_id, '5-103', 'Beban Marketing', 'beban', 'debit', true),
    (p_business_id, '5-104', 'Beban Perlengkapan', 'beban', 'debit', true),
    (p_business_id, '5-999', 'Beban Lain-lain', 'beban', 'debit', true)
  on conflict (business_id, code) do nothing;
end;
$$;

create or replace function private.on_business_created()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.seed_default_accounts(new.id);
  return new;
end;
$$;

create trigger businesses_seed_accounts
after insert on public.businesses
for each row execute function private.on_business_created();

-- Backfill for businesses that already existed before this migration.
do $$
declare
  b record;
begin
  for b in select id from public.businesses loop
    perform private.seed_default_accounts(b.id);
  end loop;
end;
$$;

-- Mechanical double-entry helper — inserts a balanced entry + its lines.
-- Callers (security-definer RPCs) are responsible for auth/ownership checks;
-- this function trusts p_business_id and only enforces that debits = credits.
create or replace function private.post_journal(
  p_business_id uuid,
  p_date timestamptz,
  p_description text,
  p_source text,
  p_source_id uuid,
  p_lines jsonb -- array of {account_code, debit, credit}
)
returns uuid
language plpgsql
set search_path = ''
as $$
declare
  v_entry_id uuid;
  v_line jsonb;
  v_account_id uuid;
  v_total_debit numeric(14, 2) := 0;
  v_total_credit numeric(14, 2) := 0;
  v_debit numeric(14, 2);
  v_credit numeric(14, 2);
begin
  if p_lines is null or jsonb_array_length(p_lines) < 2 then
    raise exception 'journal entry needs at least 2 lines';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_debit := coalesce((v_line ->> 'debit')::numeric, 0);
    v_credit := coalesce((v_line ->> 'credit')::numeric, 0);
    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
  end loop;

  if round(v_total_debit, 2) <> round(v_total_credit, 2) then
    raise exception 'unbalanced journal entry: debit % <> credit %', v_total_debit, v_total_credit;
  end if;

  insert into public.journal_entries (business_id, date, description, source, source_id)
  values (p_business_id, p_date, p_description, p_source, p_source_id)
  returning id into v_entry_id;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    select id into v_account_id
    from public.accounts
    where business_id = p_business_id and code = (v_line ->> 'account_code');

    if v_account_id is null then
      raise exception 'account not found: %', (v_line ->> 'account_code');
    end if;

    insert into public.journal_lines (entry_id, account_id, debit, credit)
    values (
      v_entry_id,
      v_account_id,
      coalesce((v_line ->> 'debit')::numeric, 0),
      coalesce((v_line ->> 'credit')::numeric, 0)
    );
  end loop;

  return v_entry_id;
end;
$$;

-- Public RPC for manual journal entries from the client.
create or replace function public.post_journal_entry(
  p_business_id uuid,
  p_date timestamptz,
  p_description text,
  p_lines jsonb -- array of {account_code, debit, credit}
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entry_id uuid;
begin
  if not private.owns_business(p_business_id) then
    raise exception 'not authorized';
  end if;

  if p_description is null or length(trim(p_description)) = 0 then
    raise exception 'description required';
  end if;

  v_entry_id := private.post_journal(
    p_business_id, coalesce(p_date, now()), p_description, 'manual', null, p_lines
  );

  return v_entry_id;
end;
$$;

grant execute on function public.post_journal_entry(uuid, timestamptz, text, jsonb) to authenticated;

