import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";

function formatRupiah(value: number) {
  return `Rp${Math.round(value).toLocaleString("id-ID")}`;
}

function formatDate(dateStr: string) {
  return new Date(`${dateStr}T00:00:00Z`).toLocaleDateString("id-ID", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });
}

const STATUS_LABELS: Record<string, string> = {
  draft: "Draft",
  unpaid: "Belum Dibayar",
  partial: "Sebagian",
  paid: "Lunas",
};

const STATUS_BADGE: Record<string, string> = {
  draft: "bg-zinc-100 text-zinc-500",
  unpaid: "bg-amber-50 text-amber-700",
  partial: "bg-blue-50 text-blue-700",
  paid: "bg-brand-50 text-brand-700",
};

type InvoiceRow = {
  id: string;
  invoice_number: string;
  customer_name: string;
  date: string;
  due_date: string | null;
  subtotal: number;
  dp_amount: number;
  status: string;
};

export default async function InvoicesPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const { data: invoices } = await supabase
    .from("invoices")
    .select("id, invoice_number, customer_name, date, due_date, subtotal, dp_amount, status")
    .eq("business_id", businessId)
    .order("date", { ascending: false })
    .order("created_at", { ascending: false })
    .limit(50);

  const rows = (invoices ?? []) as InvoiceRow[];

  return (
    <div className="w-full max-w-2xl">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h1 className="text-lg font-bold text-zinc-900">Invoice/Nota — {business.name}</h1>
          <p className="mt-0.5 text-xs text-zinc-500">
            Dokumen tagihan untuk klien — belum tercatat sebagai transaksi kasir.
          </p>
        </div>
        <Link
          href={`/business/${businessId}/invoices/baru`}
