1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { createClient } from "@/lib/supabase/server";
4	import { addExpense, addReconciliation, setOpeningInventory } from "./actions";
5	import AddExpenseForm from "./add-expense-form";
6	import AddReconciliationForm from "./add-reconciliation-form";
7	import DeleteExpenseButton from "./delete-expense-button";
8	import MerchantFeeInput from "./merchant-fee-input";
9	import SetOpeningInventoryForm from "./set-opening-inventory-form";
10	
11	const PURCHASE_INGREDIENT_CATEGORY = "Pembelian Bahan Baku";
12	const PURCHASE_PRODUCT_CATEGORY = "Pembelian Barang Dagang";
13	const PAYMENT_METHODS = ["Tunai", "Kartu", "QRIS"];
14	
15	type Period = "today" | "week" | "month" | "all";
16	
17	const PERIOD_LABELS: Record<Period, string> = {
18	  today: "Hari Ini",
19	  week: "7 Hari",
20	  month: "Bulan Ini",
21	  all: "Semua",
22	};
23	
24	function formatRupiah(value: number) {
25	  const sign = value < 0 ? "-" : "";
26	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
27	}
28	
29	function formatDate(dateStr: string) {
30	  return new Date(`${dateStr}T00:00:00Z`).toLocaleDateString("id-ID", {
31	    day: "2-digit",
32	    month: "short",
33	    year: "numeric",
34	    timeZone: "UTC",
35	  });
36	}
37	
38	function toDateStr(d: Date) {
39	  return d.toISOString().slice(0, 10);
40	}
41	
42	function addDaysStr(dateStr: string, days: number) {
43	  const d = new Date(`${dateStr}T00:00:00Z`);
44	  d.setUTCDate(d.getUTCDate() + days);
45	  return toDateStr(d);
46	}
47	
48	function getPeriodStartDateStr(period: Period): string | null {
49	  const now = new Date();
50	  if (period === "today") return toDateStr(now);
51	  if (period === "week") return addDaysStr(toDateStr(now), -6);
52	  if (period === "month") return toDateStr(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)));
53	  return null;
54	}
55	
56	function getPreviousMonthLastDayStr(): string {
57	  const now = new Date();
58	  // Day 0 of the current UTC month == last day of the previous month.
59	  return toDateStr(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0)));
60	}
