62	export default async function FinancePage({
63	  params,
64	  searchParams,
65	}: {
66	  params: Promise<{ businessId: string }>;
67	  searchParams: Promise<{ period?: string }>;
68	}) {
69	  const { businessId } = await params;
70	  const { period: periodParam } = await searchParams;
71	  const period: Period = (["today", "week", "month", "all"] as const).includes(
72	    periodParam as Period,
73	  )
74	    ? (periodParam as Period)
75	    : "month";
76	
77	  const supabase = await createClient();
78	  const today = toDateStr(new Date());
79	
80	  const { data: business } = await supabase
81	    .from("businesses")
82	    .select("id, name, business_type")
83	    .eq("id", businessId)
84	    .single();
85	
86	  if (!business) {
87	    notFound();
88	  }
89	
90	  const isFnb = business.business_type === "fnb";
91	  const periodStartStr = getPeriodStartDateStr(period);
92	
93	  const boundAddExpense = addExpense.bind(null, businessId);
94	  const boundAddReconciliation = addReconciliation.bind(null, businessId);
95	  const anchorDate = getPreviousMonthLastDayStr();
96	  const boundSetOpeningInventory = setOpeningInventory.bind(null, businessId, anchorDate);
97	
98	  // ── Transaksi periode ini (untuk pendapatan, COGS teori, rekonsiliasi) ──
99	  let txQuery = supabase
100	    .from("transactions")
101	    .select("total, total_cost, transaction_payments(method, amount)")
102	    .eq("business_id", businessId)
103	    .eq("voided", false);
104	  if (periodStartStr) txQuery = txQuery.gte("date", periodStartStr);
105	  const { data: transactions } = await txQuery;
106	
107	  const revenue = (transactions ?? []).reduce((s, t) => s + Number(t.total), 0);
108	  const cogsTeori = (transactions ?? []).reduce((s, t) => s + Number(t.total_cost), 0);
109	
110	  const byMethod = new Map<string, { count: number; totalPOS: number }>();
111	  for (const t of transactions ?? []) {
112	    for (const p of t.transaction_payments ?? []) {
113	      const entry = byMethod.get(p.method) ?? { count: 0, totalPOS: 0 };
114	      entry.count += 1;
115	      entry.totalPOS += Number(p.amount);
116	      byMethod.set(p.method, entry);
117	    }
118	  }
119	
120	  // ── Pengeluaran periode ini ──
121	  let expQuery = supabase
122	    .from("expenses")
123	    .select("id, date, category, amount, note, qty")
124	    .eq("business_id", businessId)
125	    .order("date", { ascending: false });
126	  if (periodStartStr) expQuery = expQuery.gte("date", periodStartStr);
127	  const { data: expenses } = await expQuery;
128	
129	  const purchaseExpenses = (expenses ?? []).filter(
130	    (e) => e.category === PURCHASE_INGREDIENT_CATEGORY || e.category === PURCHASE_PRODUCT_CATEGORY,
131	  );
132	  const totalPembelian = purchaseExpenses.reduce((s, e) => s + Number(e.amount), 0);
133	  const otherExpenses = (expenses ?? []).filter(
134	    (e) => e.category !== PURCHASE_INGREDIENT_CATEGORY && e.category !== PURCHASE_PRODUCT_CATEGORY,
135	  );
136	  const totalOtherExp = otherExpenses.reduce((s, e) => s + Number(e.amount), 0);
137	
138	  // ── Rekonsiliasi & biaya merchant ──
139	  const { data: merchantFeeRows } = await supabase
140	    .from("merchant_fees")
141	    .select("method, fee_percent")
142	    .eq("business_id", businessId);
143	  const merchantFeeMap = new Map((merchantFeeRows ?? []).map((r) => [r.method, Number(r.fee_percent)]));
144	
145	  let reconQuery = supabase
146	    .from("reconciliations")
147	    .select("method, actual_amount")
148	    .eq("business_id", businessId);
149	  if (periodStartStr) reconQuery = reconQuery.gte("date", periodStartStr);
150	  const { data: reconciliations } = await reconQuery;
151	
152	  const reconciliationRows = Array.from(byMethod.entries())
153	    .map(([method, { count, totalPOS }]) => {
154	      const feePct = merchantFeeMap.get(method) ?? 0;
155	      const merchantFee = Math.round((totalPOS * feePct) / 100);
156	      const estimasiNet = totalPOS - merchantFee;
157	      const matching = (reconciliations ?? []).filter((r) => r.method === method);
158	      const hasActual = matching.length > 0;
159	      const actualReceived = matching.reduce((s, r) => s + Number(r.actual_amount), 0);
160	      const selisih = hasActual ? actualReceived - estimasiNet : null;
161	      return { method, count, totalPOS, feePct, merchantFee, estimasiNet, actualReceived, hasActual, selisih };
162	    })
163	    .sort((a, b) => b.totalPOS - a.totalPOS);
164	
165	  const reconTotals = reconciliationRows.reduce(
166	    (acc, r) => ({
167	      totalPOS: acc.totalPOS + r.totalPOS,
168	      merchantFee: acc.merchantFee + r.merchantFee,
169	      estimasiNet: acc.estimasiNet + r.estimasiNet,
170	      actualReceived: acc.actualReceived + (r.hasActual ? r.actualReceived : 0),
171	    }),
172	    { totalPOS: 0, merchantFee: 0, estimasiNet: 0, actualReceived: 0 },
173	  );
174	
175	  const reconMethods = Array.from(
176	    new Set([...PAYMENT_METHODS, ...Array.from(byMethod.keys())]),
177	  );
178	
179	  const { data: openShift } = await supabase
180	    .from("shifts")
181	    .select("id")
182	    .eq("business_id", businessId)
183	    .is("closed_at", null)
184	    .limit(1)
185	    .maybeSingle();
186	
187	  // ── Kontrol HPP teori vs aktual (persediaan) ──
188	  const { data: ingredientsForCost } = await supabase
189	    .from("ingredients")
190	    .select("id, name, unit, stock, unit_cost")
191	    .eq("business_id", businessId)
192	    .is("deleted_at", null);
193	  const { data: productsForCost } = await supabase
194	    .from("products")
195	    .select("id, name, stock, cost")
196	    .eq("business_id", businessId)
197	    .is("deleted_at", null);
198	
199	  const ingredientsValue = (ingredientsForCost ?? []).reduce(
200	    (s, i) => s + Number(i.stock) * Number(i.unit_cost),
201	    0,
202	  );
203	  const productsValue = (productsForCost ?? []).reduce((s, p) => s + Number(p.stock) * Number(p.cost), 0);
204	  const closingValue = ingredientsValue + productsValue;
205	
206	  let openingValue: number | null = null;
207	  if (periodStartStr) {
208	    const dayBefore = addDaysStr(periodStartStr, -1);
209	    const { data: snapshot } = await supabase
210	      .from("inventory_snapshots")
211	      .select("value")
212	      .eq("business_id", businessId)
213	      .lte("date", dayBefore)
214	      .order("date", { ascending: false })
215	      .limit(1)
216	      .maybeSingle();
217	    openingValue = snapshot ? Number(snapshot.value) : null;
218	  } else {
219	    const { data: snapshot } = await supabase
220	      .from("inventory_snapshots")
221	      .select("value")
222	      .eq("business_id", businessId)
223	      .order("date", { ascending: true })
224	      .limit(1)
225	      .maybeSingle();
226	    openingValue = snapshot ? Number(snapshot.value) : null;
227	  }
228	  const usedFallback = openingValue === null;
229	  if (openingValue === null) openingValue = closingValue;
230	
231	  const cogsAktual = openingValue + totalPembelian - closingValue;
232	  const netProfit = revenue - cogsAktual - totalOtherExp;
233	
234	  const selisih = cogsAktual - cogsTeori;
235	  const selisihPct = cogsTeori > 0 ? Math.round((selisih / cogsTeori) * 100) : 0;
236	
237	  let selisihBoxClass = "bg-zinc-100 text-zinc-500";
238	  let selisihNote = "";
239	  if (usedFallback) {
240	    selisihBoxClass = "bg-zinc-100 text-zinc-500";
241	    selisihNote =
242	      "Belum ada histori persediaan sebelum periode ini, jadi Persediaan Awal disamakan dengan Persediaan Akhir (COGS Aktual = Total Pembelian saja untuk sementara). Akurasi akan membaik setelah beberapa hari histori snapshot terkumpul.";
243	  } else if (cogsTeori === 0) {
244	    selisihBoxClass = "bg-zinc-100 text-zinc-500";
245	    selisihNote = "Belum ada penjualan dengan resep HPP di periode ini — COGS Teori belum bisa dibandingkan.";
246	  } else if (Math.abs(selisihPct) <= 10) {
247	    selisihBoxClass = "bg-brand-50 text-brand-700";
248	    selisihNote = "Selisih wajar (≤10%) — pemakaian bahan baku aktual cukup sejalan dengan teori resep.";
249	  } else if (selisih > 0) {
250	    selisihBoxClass = "bg-red-50 text-red-600";
251	    selisihNote =
252	      "Konsumsi bahan baku aktual lebih besar dari teori resep — indikasi waste, porsi kelebihan takaran, atau bahan terpakai di luar resep tercatat.";
253	  } else {
254	    selisihBoxClass = "bg-amber-50 text-amber-700";
255	    selisihNote =
256	      "Konsumsi bahan baku aktual lebih kecil dari teori resep — kemungkinan ada efisiensi, atau resep belum mencerminkan pemakaian bahan yang sesungguhnya.";
257	  }
258	
259	  const { data: existingOpeningSnapshot } = await supabase
260	    .from("inventory_snapshots")
261	    .select("value")
262	    .eq("business_id", businessId)
263	    .eq("date", anchorDate)
264	    .eq("manual", true)
265	    .maybeSingle();
266	
267	  return (
268	    <div className="w-full max-w-3xl">
269	        <div className="flex flex-wrap items-center justify-between gap-2">
270	          <h1 className="text-lg font-bold text-zinc-900">Keuangan — {business.name}</h1>
271	          <div className="flex flex-wrap gap-1.5">
272	            {(["today", "week", "month", "all"] as Period[]).map((p) => (
273	              <Link
274	                key={p}
275	                href={`/business/${businessId}/finance?period=${p}`}
276	                className={`rounded-full px-3 py-1 text-xs font-medium transition-colors ${
277	                  p === period
278	                    ? "bg-brand-600 text-white"
279	                    : "bg-white text-zinc-600 hover:bg-zinc-100"
280	                }`}
281	              >
282	                {PERIOD_LABELS[p]}
283	              </Link>
284	            ))}
285	          </div>
286	        </div>
287	
288	        {/* Ringkasan */}
289	        <div className="mt-6 grid grid-cols-2 gap-3">
290	          <div className="rounded-xl bg-white shadow-sm p-4">
291	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Total Pendapatan</p>
292	            <p className="text-lg font-bold text-zinc-900">{formatRupiah(revenue)}</p>
293	          </div>
294	          <div className="rounded-xl bg-white shadow-sm p-4">
295	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">Beban Operasional</p>
296	            <p className="text-lg font-bold text-zinc-900">{formatRupiah(totalOtherExp)}</p>
297	            <p className="mt-0.5 text-[10px] text-zinc-400">di luar bahan baku</p>
298	          </div>
299	          <div className="col-span-2 rounded-2xl bg-brand-700 p-4">
300	            <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-brand-200">Laba Bersih</p>
301	            <p className="text-lg font-bold text-white">{formatRupiah(netProfit)}</p>
302	            <p className="mt-0.5 text-[10px] text-brand-200">pendapatan − COGS aktual − beban</p>
303	          </div>
304	        </div>
305	
306	        {/* Rekonsiliasi */}
307	        <div className="mt-6 overflow-hidden rounded-xl bg-white shadow-sm">
308	          <div className="border-b border-zinc-100 px-4 py-3.5">
309	            <h2 className="text-sm font-bold text-zinc-900">Rekonsiliasi Pembayaran &amp; Biaya Merchant</h2>
310	            <p className="mt-0.5 text-[11px] text-zinc-400">
311	              Sandingkan yang tercatat di POS vs yang benar-benar masuk ke rekening/saldo, setelah
312	              dipotong biaya merchant.
313	            </p>
314	          </div>
315	
316	          {reconciliationRows.length > 0 ? (
317	            <div className="overflow-x-auto">
318	              <table className="w-full text-xs">
