336	                          {r.count} transaksi
337	                        </span>
338	                      </td>
339	                      <td className="px-3 py-2.5 text-right text-zinc-700">{formatRupiah(r.totalPOS)}</td>
340	                      <td className="px-3 py-2.5 text-center">
