function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("id-ID", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function parsePeriod(value: string | undefined): Period {
  return value === "30" || value === "90" ? value : "all";
